mapper.update:
UPDATE CHAT_ROOM
SET last_message = #{lastMessage}, last_message_at = NOW()
WHERE chat_room_id = #{chatRoomId}

UPDATE CHAT_ROOM cr
INNER JOIN EXCLUSIVE e ON e.exclusive_id = cr.exclusive_id
SET cr.status = #{status}
WHERE cr.chat_room_id = #{chatRoomId} AND e.user_id = #{userId}
